    //==========================================================================
    //                          Xoroshiro128++  (MC 1.18+)
    //==========================================================================
    static final class Xoroshiro {
        long lo, hi;

        void setSeed(long value) {
            final long XL = 0x9e3779b97f4a7c15L, XH = 0x6a09e667f3bcc909L;
            final long A = 0xbf58476d1ce4e5b9L, B = 0x94d049bb133111ebL;
            long l = value ^ XH;
            long h = l + XL;
            l = (l ^ (l >>> 30)) * A;
            h = (h ^ (h >>> 30)) * A;
            l = (l ^ (l >>> 27)) * B;
            h = (h ^ (h >>> 27)) * B;
            lo = l ^ (l >>> 31);
            hi = h ^ (h >>> 31);
        }

        long nextLong() {
            long l = lo, h = hi;
            long n = Long.rotateLeft(l + h, 17) + l;
            h ^= l;
            lo = Long.rotateLeft(l, 49) ^ h ^ (h << 21);
            hi = Long.rotateLeft(h, 28);
            return n;
        }

        int nextInt(int n) { // n > 0
            long r = (nextLong() & 0xFFFFFFFFL) * n;
            if (Integer.compareUnsigned((int) r, n) < 0) {
                final int lim = (int) (((1L << 32) - n) % n);
                while (Integer.compareUnsigned((int) r, lim) < 0)
                    r = (nextLong() & 0xFFFFFFFFL) * n;
            }
            return (int) (r >>> 32);
        }

        double nextDouble() {
            return (nextLong() >>> 11) * 1.1102230246251565E-16;
        }
    }

    //==========================================================================
    //                              Perlin 噪声
    //==========================================================================
    static final class Perlin {
        final int[] d = new int[257];
        int h2;
        double a, b, c, d2, t2, amplitude = 1.0, lacunarity = 1.0;
    }

    static final class Oct {
        Perlin[] p = new Perlin[0];
        int n;
    }

    static final class DoublePerlin {
        double amplitude;
        final Oct octA = new Oct(), octB = new Oct();
    }

    static double lerpD(double part, double from, double to) {
        return from + part * (to - from);
    }

    static double indexedLerp(int idx, double a, double b, double c) {
        switch (idx & 0xf) {
        case 0:  return  a + b;
        case 1:  return -a + b;
        case 2:  return  a - b;
        case 3:  return -a - b;
        case 4:  return  a + c;
        case 5:  return -a + c;
        case 6:  return  a - c;
        case 7:  return -a - c;
        case 8:  return  b + c;
        case 9:  return -b + c;
        case 10: return  b - c;
        case 11: return -b - c;
        case 12: return  a + b;
        case 13: return -b + c;
        case 14: return -a + b;
        case 15: return -b - c;
        }
        throw new AssertionError("indexedLerp");
    }

    static void xPerlinInit(Perlin p, Xoroshiro xr) {
        p.a = xr.nextDouble() * 256.0;
        p.b = xr.nextDouble() * 256.0;
        p.c = xr.nextDouble() * 256.0;
        p.amplitude = 1.0;
        p.lacunarity = 1.0;
        int[] idx = p.d;
        for (int i = 0; i < 256; i++) idx[i] = i;
        for (int i = 0; i < 256; i++) {
            int j = xr.nextInt(256 - i) + i;
            int t = idx[i]; idx[i] = idx[j]; idx[j] = t;
        }
        idx[256] = idx[0];
        double i2 = Math.floor(p.b);
        double dd = p.b - i2;
        p.h2 = (int) i2 & 0xFF;
        p.d2 = dd;
        p.t2 = dd * dd * dd * (dd * (dd * 6.0 - 15.0) + 10.0);
    }

    static double samplePerlin(Perlin p, double d1, double d2, double d3,
            double yamp, double ymin) {
        int h1, h2, h3;
        double t1, t2, t3;

        if (d2 == 0.0) {
            d2 = p.d2; h2 = p.h2; t2 = p.t2;
        } else {
            d2 += p.b;
            double i2 = Math.floor(d2);
            d2 -= i2;
            h2 = (int) i2 & 0xFF;
            t2 = d2 * d2 * d2 * (d2 * (d2 * 6.0 - 15.0) + 10.0);
        }

        d1 += p.a;
        d3 += p.c;

        double i1 = Math.floor(d1), i3 = Math.floor(d3);
        d1 -= i1; d3 -= i3;

        h1 = (int) i1 & 0xFF;
        h3 = (int) i3 & 0xFF;

        t1 = d1 * d1 * d1 * (d1 * (d1 * 6.0 - 15.0) + 10.0);
        t3 = d3 * d3 * d3 * (d3 * (d3 * 6.0 - 15.0) + 10.0);

        if (yamp != 0.0) {
            double yclamp = Math.min(ymin, d2);
            d2 -= Math.floor(yclamp / yamp) * yamp;
        }

        int[] idx = p.d;
        int a1 = (idx[h1]     + h2) & 0xFF;
        int b1 = (idx[h1 + 1] + h2) & 0xFF;
        int a2 = (idx[a1]     + h3) & 0xFF;
        int b2 = (idx[b1]     + h3) & 0xFF;
        int a3 = (idx[a1 + 1] + h3) & 0xFF;
        int b3 = (idx[b1 + 1] + h3) & 0xFF;

        double l1 = indexedLerp(idx[a2],     d1,     d2,     d3);
        double l2 = indexedLerp(idx[b2],     d1 - 1, d2,     d3);
        double l3 = indexedLerp(idx[a3],     d1,     d2 - 1, d3);
        double l4 = indexedLerp(idx[b3],     d1 - 1, d2 - 1, d3);
        double l5 = indexedLerp(idx[a2 + 1], d1,     d2,     d3 - 1);
        double l6 = indexedLerp(idx[b2 + 1], d1 - 1, d2,     d3 - 1);
        double l7 = indexedLerp(idx[a3 + 1], d1,     d2 - 1, d3 - 1);
        double l8 = indexedLerp(idx[b3 + 1], d1 - 1, d2 - 1, d3 - 1);

        l1 = lerpD(t1, l1, l2); l3 = lerpD(t1, l3, l4);
        l5 = lerpD(t1, l5, l6); l7 = lerpD(t1, l7, l8);
        l1 = lerpD(t2, l1, l3); l5 = lerpD(t2, l5, l7);
        return lerpD(t3, l1, l5);
    }

    static double sampleOctave(Oct o, double x, double y, double z) {
        double v = 0;
        for (int i = 0; i < o.n; i++) {
            Perlin p = o.p[i];
            double lf = p.lacunarity;
            double pv = samplePerlin(p, x * lf, y * lf, z * lf, 0, 0);
            v += p.amplitude * pv;
        }
        return v;
    }

    static double sampleDoublePerlin(DoublePerlin dp, double x, double y, double z) {
        final double f = 337.0 / 331.0;
        double v = sampleOctave(dp.octA, x, y, z);
        v += sampleOctave(dp.octB, x * f, y * f, z * f);
        return v * dp.amplitude;
    }

    static final long[][] MD5_OCT = {
        {0xb198de63a8012672L, 0x7b84cad43ef7b5a8L}, // md5 "octave_-12"
        {0x0fd787bfbc403ec3L, 0x74a4a31ca21b48b8L}, // md5 "octave_-11"
        {0x36d326eed40efeb2L, 0x5be9ce18223c636aL}, // md5 "octave_-10"
        {0x082fe255f8be6631L, 0x4e96119e22dedc81L}, // md5 "octave_-9"
        {0x0ef68ec68504005eL, 0x48b6bf93a2789640L}, // md5 "octave_-8"
        {0xf11268128982754fL, 0x257a1d670430b0aaL}, // md5 "octave_-7"
        {0xe51c98ce7d1de664L, 0x5f9478a733040c45L}, // md5 "octave_-6"
        {0x6d7b49e7e429850aL, 0x2e3063c622a24777L}, // md5 "octave_-5"
        {0xbd90d5377ba1b762L, 0xc07317d419a7548dL}, // md5 "octave_-4"
        {0x53d39c6752dac858L, 0xbcd1c5a80ab65b3eL}, // md5 "octave_-3"
        {0xb4a24d7a84e7677bL, 0x023ff9668e89b5c4L}, // md5 "octave_-2"
        {0xdffa22b534c5f608L, 0xb9b67517d3665ca9L}, // md5 "octave_-1"
        {0xd50708086cef4d7cL, 0x6e1651ecc7f43309L}, // md5 "octave_0"
    };
    static final double[] LACUNA_INI = {
        1, 0.5, 0.25, 1.0 / 8, 1.0 / 16, 1.0 / 32, 1.0 / 64, 1.0 / 128,
        1.0 / 256, 1.0 / 512, 1.0 / 1024, 1.0 / 2048, 1.0 / 4096,
    };
    static final double[] PERSIST_INI = {
        0, 1, 2.0 / 3, 4.0 / 7, 8.0 / 15, 16.0 / 31, 32.0 / 63, 64.0 / 127,
        128.0 / 255, 256.0 / 511,
    };
    static final double[] AMP_INI = { // (5/3)*len/(len+1)
        0, 5.0 / 6, 10.0 / 9, 15.0 / 12, 20.0 / 15, 25.0 / 18, 30.0 / 21,
        35.0 / 24, 40.0 / 27, 45.0 / 30,
    };

    static int xOctaveInit(Oct o, Xoroshiro xr, double[] amp, int omin, int len, int nmax) {
        double lacuna = LACUNA_INI[-omin];
        double persist = PERSIST_INI[len];
        long xlo = xr.nextLong(), xhi = xr.nextLong();
        Perlin[] buf = new Perlin[len];
        int n = 0;
        for (int i = 0; i < len && n != nmax; i++, lacuna *= 2.0, persist *= 0.5) {
            if (amp[i] == 0) continue;
            Xoroshiro pxr = new Xoroshiro();
            pxr.lo = xlo ^ MD5_OCT[12 + omin + i][0];
            pxr.hi = xhi ^ MD5_OCT[12 + omin + i][1];
            Perlin pn = new Perlin();
            xPerlinInit(pn, pxr);
            pn.amplitude = amp[i] * persist;
            pn.lacunarity = lacuna;
            buf[n++] = pn;
        }
        o.p = buf;
        o.n = n;
        return n;
    }

    static int xDoublePerlinInit(DoublePerlin dp, Xoroshiro xr,
            double[] amp, int omin, int len, int nmax) {
        int na = -1, nb = -1;
        if (nmax > 0) { na = (nmax + 1) >> 1; nb = nmax - na; }
        int n = xOctaveInit(dp.octA, xr, amp, omin, len, na);
        n += xOctaveInit(dp.octB, xr, amp, omin, len, nb);
        int L = len, i;
        for (i = L - 1; i >= 0 && amp[i] == 0.0; i--) L--;
        for (i = 0; amp[i] == 0.0; i++) L--;
        dp.amplitude = AMP_INI[L];
        return n;
    }

    //==========================================================================
    //                    气候噪声初始化 (盐值来自 vanilla md5)
    //==========================================================================
    static final int NP_TEMP = 0, NP_HUM = 1, NP_CONT = 2, NP_EROS = 3,
                     NP_SHIFT = 4, NP_WEIRD = 5, NP_MAX = 6;

    static void initClimateSeed(DoublePerlin dp, long xlo, long xhi,
            boolean large, int np) {
        Xoroshiro pxr = new Xoroshiro();
        switch (np) {
        case NP_SHIFT: {
            double[] amp = {1, 1, 1, 0};
            pxr.lo = xlo ^ 0x080518cf6af25384L;            // md5 "minecraft:offset"
            pxr.hi = xhi ^ 0x3f3dfb40a54febd5L;
            xDoublePerlinInit(dp, pxr, amp, -3, 4, -1);
        } break;
        case NP_TEMP: {
            double[] amp = {1.5, 0, 1, 0, 0, 0};
            pxr.lo = xlo ^ (large ? 0x944b0073edf549dbL : 0x5c7e6b29735f0d7fL);
            pxr.hi = xhi ^ (large ? 0x4ff44347e9d22b96L : 0xf7d86f1bbc734988L);
            xDoublePerlinInit(dp, pxr, amp, large ? -12 : -10, 6, -1);
        } break;
        case NP_HUM: {
            double[] amp = {1, 1, 0, 0, 0, 0};
            pxr.lo = xlo ^ (large ? 0x71b8ab943dbd5301L : 0x81bb4d22e8dc168eL);
            pxr.hi = xhi ^ (large ? 0xbb63ddcf39ff7a2bL : 0xf1c8b4bea16303cdL);
            xDoublePerlinInit(dp, pxr, amp, large ? -10 : -8, 6, -1);
        } break;
        case NP_CONT: {
            double[] amp = {1, 1, 2, 2, 2, 1, 1, 1, 1};
            pxr.lo = xlo ^ (large ? 0x9a3f51a113fce8dcL : 0x83886c9d0ae3a662L);
            pxr.hi = xhi ^ (large ? 0xee2dbd157e5dcdadL : 0xafa638a61b42e8adL);
            xDoublePerlinInit(dp, pxr, amp, large ? -11 : -9, 9, -1);
        } break;
        case NP_EROS: {
            double[] amp = {1, 1, 0, 1, 1};
            pxr.lo = xlo ^ (large ? 0x8c984b1f8702a951L : 0xd02491e6058f6fd8L);
            pxr.hi = xhi ^ (large ? 0xead7b1f92bae535fL : 0x4792512c94c17a80L);
            xDoublePerlinInit(dp, pxr, amp, large ? -11 : -9, 5, -1);
        } break;
        case NP_WEIRD: {
            double[] amp = {1, 2, 1, 0, 0, 0};
            pxr.lo = xlo ^ 0xefc8ef4d36102b34L;            // md5 "minecraft:ridge"
            pxr.hi = xhi ^ 0x1beeeb324a0f24eaL;
            xDoublePerlinInit(dp, pxr, amp, -7, 6, -1);
        } break;
        default: throw new AssertionError("climate param");
        }
    }

    //==========================================================================
    //                  地形偏移样条 (计算深度参数 depth 所需)
    //==========================================================================
    static final int SP_CONT = 0, SP_EROS = 1, SP_RIDGES = 2, SP_WEIRD = 3;

    static final class Spline {
        int typ;
        int len;
        float val; // len==1 时为常量样条
        final float[] loc = new float[12];
        final Spline[] valArr = new Spline[12];
        final float[] der = new float[12];
    }

    static Spline spline(int typ) {
        Spline s = new Spline();
        s.typ = typ;
        return s;
    }

    static Spline fix(float v) {
        Spline s = new Spline();
        s.len = 1;
        s.val = v;
        return s;
    }

    static void addVal(Spline sp, float loc, Spline val, float der) {
        sp.loc[sp.len] = loc;
        sp.valArr[sp.len] = val;
        sp.der[sp.len] = der;
        sp.len++;
    }

    static float getOffsetValue(float weirdness, float continentalness) {
        float f0 = 1.0F - (1.0F - continentalness) * 0.5F;
        float f1 = 0.5F * (1.0F - continentalness);
        float f2 = (weirdness + 1.17F) * 0.46082947F;
        float off = f2 * f0 - f1;
        if (weirdness < -0.7F)
            return off > -0.2222F ? off : -0.2222F;
        else
            return off > 0 ? off : 0;
    }

    static Spline createSpline38219(float f, boolean bl) {
        Spline sp = spline(SP_RIDGES);
        float i = getOffsetValue(-1.0F, f);
        float k = getOffsetValue( 1.0F, f);
        float l = 1.0F - (1.0F - f) * 0.5F;
        float u = 0.5F * (1.0F - f);
        l = u / (0.46082947F * l) - 1.17F;
        if (-0.65F < l && l < 1.0F) {
            u = getOffsetValue(-0.65F, f);
            float p = getOffsetValue(-0.75F, f);
            float q = (p - i) * 4.0F;
            float r = getOffsetValue(l, f);
            float s = (k - r) / (1.0F - l);
            addVal(sp, -1.0F,   fix(i), q);
            addVal(sp, -0.75F,  fix(p), 0);
            addVal(sp, -0.65F,  fix(u), 0);
            addVal(sp, l-0.01F, fix(r), 0);
            addVal(sp, l,       fix(r), s);
            addVal(sp, 1.0F,    fix(k), s);
        } else {
            u = (k - i) * 0.5F;
            if (bl) {
                float iv = (float)(i > 0.2 ? (double) i : 0.2);
                addVal(sp, -1.0F, fix(iv), 0);
                addVal(sp,  0.0F, fix((float) lerpD(0.5F, i, k)), u);
            } else {
                addVal(sp, -1.0F, fix(i), u);
            }
            addVal(sp, 1.0F, fix(k), u);
        }
        return sp;
    }

    static Spline createFlatOffsetSpline(float f, float g, float h, float i,
            float j, float k) {
        Spline sp = spline(SP_RIDGES);
        float l = 0.5F * (g - f); if (l < k) l = k;
        float m = 5.0F * (h - g);
        addVal(sp, -1.0F, fix(f), l);
        addVal(sp, -0.4F, fix(g), l < m ? l : m);
        addVal(sp,  0.0F, fix(h), m);
        addVal(sp,  0.4F, fix(i), 2.0F * (i - h));
        addVal(sp,  1.0F, fix(j), 0.7F * (j - i));
        return sp;
    }

    static Spline createLandSpline(float f, float g, float h, float i,
            float j, float k, boolean bl) {
        Spline sp1 = createSpline38219((float) lerpD(i, 0.6F, 1.5F), bl);
        Spline sp2 = createSpline38219((float) lerpD(i, 0.6F, 1.0F), bl);
        Spline sp3 = createSpline38219(i, bl);
        float ih = 0.5F * i;
        Spline sp4 = createFlatOffsetSpline(f-0.15F, ih, ih, ih, i*0.6F, 0.5F);
        Spline sp5 = createFlatOffsetSpline(f, j*i, g*i, ih, i*0.6F, 0.5F);
        Spline sp6 = createFlatOffsetSpline(f, j, j, g, h, 0.5F);
        Spline sp7 = createFlatOffsetSpline(f, j, j, g, h, 0.5F);

        Spline sp8 = spline(SP_RIDGES);
        addVal(sp8, -1.0F, fix(f), 0.0F);
        addVal(sp8, -0.4F, sp6, 0.0F);
        addVal(sp8,  0.0F, fix(h + 0.07F), 0.0F);

        Spline sp9 = createFlatOffsetSpline(-0.02F, k, k, g, h, 0.0F);
        Spline sp = spline(SP_EROS);
        addVal(sp, -0.85F, sp1, 0.0F);
        addVal(sp, -0.7F,  sp2, 0.0F);
        addVal(sp, -0.4F,  sp3, 0.0F);
        addVal(sp, -0.35F, sp4, 0.0F);
        addVal(sp, -0.1F,  sp5, 0.0F);
        addVal(sp,  0.2F,  sp6, 0.0F);
        if (bl) {
            addVal(sp, 0.4F,  sp7, 0.0F);
            addVal(sp, 0.45F, sp8, 0.0F);
            addVal(sp, 0.55F, sp8, 0.0F);
            addVal(sp, 0.58F, sp7, 0.0F);
        }
        addVal(sp, 0.7F, sp9, 0.0F);
        return sp;
    }

    static Spline buildOffsetSpline() {
        Spline sp = spline(SP_CONT);
        Spline sp1 = createLandSpline(-0.15F, 0.00F, 0.0F, 0.1F, 0.00F, -0.03F, false);
        Spline sp2 = createLandSpline(-0.10F, 0.03F, 0.1F, 0.1F, 0.01F, -0.03F, false);
        Spline sp3 = createLandSpline(-0.10F, 0.03F, 0.1F, 0.7F, 0.01F, -0.03F, true);
        Spline sp4 = createLandSpline(-0.05F, 0.03F, 0.1F, 1.0F, 0.01F,  0.01F, true);
        addVal(sp, -1.10F, fix( 0.044F), 0.0F);
        addVal(sp, -1.02F, fix(-0.2222F), 0.0F);
        addVal(sp, -0.51F, fix(-0.2222F), 0.0F);
        addVal(sp, -0.44F, fix(-0.12F), 0.0F);
        addVal(sp, -0.18F, fix(-0.12F), 0.0F);
        addVal(sp, -0.16F, sp1, 0.0F);
        addVal(sp, -0.15F, sp1, 0.0F);
        addVal(sp, -0.10F, sp2, 0.0F);
        addVal(sp,  0.25F, sp3, 0.0F);
        addVal(sp,  1.00F, sp4, 0.0F);
        return sp;
    }

    static float getSpline(Spline sp, float[] vals) {
        if (sp.len == 1)
            return sp.val;
        float f = vals[sp.typ];
        int i;
        for (i = 0; i < sp.len; i++)
            if (sp.loc[i] >= f)
                break;
        if (i == 0 || i == sp.len) {
            if (i != 0) i--;
            float v = getSpline(sp.valArr[i], vals);
            return v + sp.der[i] * (f - sp.loc[i]);
        }
        Spline sp1 = sp.valArr[i-1];
        Spline sp2 = sp.valArr[i];
        float g = sp.loc[i-1];
        float h = sp.loc[i];
        float k = (f - g) / (h - g);
        float l = sp.der[i-1];
        float m = sp.der[i];
        float n = getSpline(sp1, vals);
        float o = getSpline(sp2, vals);
        float p = l * (h - g) - (o - n);
        float q = -m * (h - g) + (o - n);
        float kf = k * (1.0F - k);
        double r = lerpD(k, n, o) + kf * lerpD(k, p, q);
        return (float) r;
    }

    //==========================================================================
    //                        生物群系噪声与采样
    //==========================================================================
    static final int B_MUSHROOM = 14; // mushroom_fields

    static final class BiomeNoise {
        final int ver;
        final DoublePerlin[] climate = new DoublePerlin[NP_MAX];
        final Spline root = buildOffsetSpline();

        BiomeNoise(int ver) { this.ver = ver; }

        void setSeed(long seed, boolean large) {
            Xoroshiro xr = new Xoroshiro();
            xr.setSeed(seed);
            long xlo = xr.nextLong();
            long xhi = xr.nextLong();
            for (int i = 0; i < NP_MAX; i++) {
                climate[i] = new DoublePerlin();
                initClimateSeed(climate[i], xlo, xhi, large, i);
            }
        }
    }

    /** 输入 quart 坐标 (方块坐标/4)。返回群系 ID, npOut 可为 null。 */
    static int sampleBiomeNoise(BiomeNoise bn, long[] npOut, int x, int y, int z) {
        float t, h, c, e, d, w;
        double px = x, pz = z;
        px += sampleDoublePerlin(bn.climate[NP_SHIFT], x, 0, z) * 4.0;
        pz += sampleDoublePerlin(bn.climate[NP_SHIFT], z, x, 0) * 4.0;

        c = (float) sampleDoublePerlin(bn.climate[NP_CONT], px, 0, pz);
        e = (float) sampleDoublePerlin(bn.climate[NP_EROS], px, 0, pz);
        w = (float) sampleDoublePerlin(bn.climate[NP_WEIRD], px, 0, pz);

        {
            float[] npParam = {
                c, e,
                -3.0F * (Math.abs(Math.abs(w) - 0.6666667F) - 0.33333334F),
                w,
            };
            double off = getSpline(bn.root, npParam) + 0.015F;
            d = (float) (1.0 - (y * 4) / 128.0 - 83.0 / 160.0 + off);
        }

        t = (float) sampleDoublePerlin(bn.climate[NP_TEMP], px, 0, pz);
        h = (float) sampleDoublePerlin(bn.climate[NP_HUM], px, 0, pz);

        long[] np = npOut != null ? npOut : new long[6];
        np[0] = (long) (10000.0F * t);
        np[1] = (long) (10000.0F * h);
        np[2] = (long) (10000.0F * c);
        np[3] = (long) (10000.0F * e);
        np[4] = (long) (10000.0F * d);
        np[5] = (long) (10000.0F * w);

        return climateToBiome(bn.ver, np);
    }

