            f.resetBtn = new JButton(t("重置搜索区域为±16384", "Reset region to ±16384"));
            f.selfTestBtn = new JButton(t("算法自检", "Self test"));
            f.pauseBtn.setEnabled(false);
            f.stopBtn.setEnabled(false);
